package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim a person on a sheet has made: an amount (0.00 or more), a date, a note (may be empty) and a
 *  status (starting DRAFT), once opened, its number on the sheet and, once settled, its fixed due. */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** Given when opened, the next on its sheet; none while a draft, cleared when voided. */
    @Column(name = "claim_number")
    private Integer number;

    /** Fixed when settled (amount × rate / 100, two decimals); none while live or when no rate applied. */
    @Column(name = "settled_due", precision = 14, scale = 2)
    private BigDecimal settledDue;

    protected Claim() {
    }

    public Claim(String sheetId, Long personId) {
        this.sheetId = sheetId;
        this.personId = personId;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    public Integer getNumber() {
        return number;
    }

    public void setNumber(Integer number) {
        this.number = number;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }
}
=== OpenClaim.java
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Moves the claim to OPEN, refusing it when its status does not allow that, and gives it the sheet's
 *  next number. */
public class OpenClaim {
    public void apply(@Val Claim claim, ClaimRepository repository) throws InvalidClaimStatusException {
        ClaimTransition.check(claim.getStatus(), ClaimStatus.OPEN);
        // Taking the number holds the sheet's numbers until this change commits or is refused. Then
        // re-check the stored status: an open of the same claim that got there first has committed by
        // now, so this one is refused (and its number rolls back with it).
        repository.takeClaimNumber(claim.getSheetId());
        ClaimTransition.check(ClaimStatus.valueOf(repository.storedStatus(claim.getId())), ClaimStatus.OPEN);
        int number = repository.lastClaimNumber(claim.getSheetId());
        ClaimTransition.to(claim, ClaimStatus.OPEN);
        claim.setNumber(number);
    }
}
=== SettleClaim.java
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.plugin.variable.Val;

/** Moves the claim to SETTLED, refusing it when its status does not allow that, and fixes its due at the
 *  rate its person's grade has in force on the claim's date: amount × rate / 100, rounded half up (none when no rate applies). */
public class SettleClaim {
    public void apply(@Val Claim claim, PersonRepository people, RateRepository rates)
            throws InvalidClaimStatusException {
        ClaimTransition.to(claim, ClaimStatus.SETTLED);
        Person person = people.findById(claim.getPersonId()).orElseThrow();
        claim.setSettledDue(rates.findInForce(claim.getSheetId(), person.getGrade(), claim.getDate())
                .map((r) -> claim.getAmount().multiply(r.getRate())
                        .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP))
                .orElse(null));
    }
}
=== ClaimTransition.java
package net.officefloor.hq.app.claim;

/** Moves a claim to a new status, refusing a change its current status does not allow. */
final class ClaimTransition {
    private ClaimTransition() {
    }

    static void to(Claim claim, ClaimStatus to) throws InvalidClaimStatusException {
        check(claim.getStatus(), to);
        claim.setStatus(to);
    }

    static void check(ClaimStatus from, ClaimStatus to) throws InvalidClaimStatusException {
        if (!from.canBecome(to)) {
            throw new InvalidClaimStatusException("A " + from + " claim cannot become " + to + ".");
        }
    }
}
